#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long original = n;
    long long rev = 0;
    while (n > 0) {
        rev = rev * 10 + n % 10;
        n = n / 10;
    }
    if (rev == original) {
        cout << "yes" << endl;
    } else {
        cout << "no" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long original = n;
        long rev = 0;
        while (n > 0) {
            rev = rev * 10 + n % 10;
            n = n / 10;
        }
        if (rev == original) {
            System.out.println("yes");
        } else {
            System.out.println("no");
        }
    }
}
